	"ntry.isDirectory; });\n  var chain = Promise.resolve();\n\n  entries.forEach(function (entry) {\n    cha"
	"in = chain.then(function () { return walkEntry(entry, \"\", files); });\n  });\n\n  chain.then(function ("
	") {\n    if (files.length) { enqueue(files, anyFolder); }\n  });\n});\n\n/* --- go ----------------------"
	"------------------------------------------- */\n\nfetch(\"hostname\", { cache: \"no-store\" })\n  .then(fun"
	"ction (res) { return res.ok \? res.text() : \"\"; })\n  .then(function (name) {\n    deviceName = (name |"
	"| \"\").trim().toUpperCase();\n    if (deviceName) { draw(); } // the title and the first crumb are its"
	" name\n  })\n  .catch(function () { /* the name is decoration; the page works without it */ });\n\nupdat"
	"eHiddenButton();\nload(CARD);\n</script>\n</body>\n</html>\n";

#endif /* WEBPAGE_H */
